procedures_and_commands.command:
f=docs/developer-feedback/observations.md; for i in 001 002 003 004 005 006 007; do grep -q "DX-$i" "$f" || echo "MISSING DX-$i"; done; python3 -I -c 'import re,sys
t=open(sys.argv[1],encoding="utf-8").read()
m=re.search(r"^#+ *Observations *\n(?:[^|\n].*\n|\n)*((?:\|.*(?:\n|$))+)",t,re.M|re.I)
r=[[c.strip() for c in l.strip().strip("|").split("|")] for l in m.group(1).splitlines()] if m else []
if not r: print("MISSING table Observations")
for x in r[2:]:
    if len(x)!=len(r[0]): print("BAD row "+x[0]+": "+str(len(x))+" cells, header has "+str(len(r[0])))
    elif "" in x: print("EMPTY cell in "+x[0]+": "+r[0][x.index("")])
' "$f"; python3 tools/ci/check_paths.py --files "$f"
